-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.quota_rows()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  n integer;
begin
  execute format('select count(*) from public.%I where user_id = $1', tg_table_name) into n using new.user_id;
  if n > tg_argv[0]::integer then
    raise exception 'quota_exceeded' using errcode = 'P0001', detail = tg_table_name;
  end if;
  return null;
end;
$function$;

grant execute on function public.quota_rows() to service_role;
